using System;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GravitationalReagentOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/GravitationalReagent Omen Data")]
public class GravitationalReagentOmenData : AstriumActivatedOmenData
{
	[Header("Gravitational Reagent Omen")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private BattleAction karmaAction;

	[SerializeField]
	private int karmaAmount;

	[SerializeField]
	private OmenLogic karmaOmenLogic;

	[SerializeField]
	private int astriumAppliedIncrease = 1;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<OrionOmensHandler>.Instance.GravitationalReagentOmenAction = (int effectAmount) => effectAmount + astriumAppliedIncrease;
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<OrionOmensHandler>.Instance.GravitationalReagentOmenAction = null;
	}

	protected override Action GetOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (currentCorruptedAnimals.IsAnyEnemyActive() && !ReferenceSingleton<GameStateManager>.Instance.IsOnDeathState)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.DrawTurn)
				{
					ReferenceSingleton<PlayerDiceHandHolder>.Instance.ModifyDrawDicesAmountModifier(ActionValue);
					ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDrawDiceAmountWithOmensModifiers();
				}
				else
				{
					DrawAction drawAction = BattleAction as DrawAction;
					if (drawAction.CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.PLAYER))
					{
						drawAction.CastAmount(ActionValue, null);
						karmaOmenLogic.ActivateOmen(karmaAction, karmaAmount, null, null);
					}
				}
			}
		};
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), astriumAppliedIncrease) + "\n" + Smart.Format(arg1: string.Format(arg0: GetOmenConvertedDescriptionBattleAction().RemoveLast().LowercaseFirst(), arg1: karmaAction.GetActionDescription(karmaAmount).LowercaseFirst(), format: ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedGainWithDrawBack()), format: base.localizationManager.GetLocalizedWhenTriggered(), arg0: astriumEffect.GetEffectName());
	}
}
